355 |   var order = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"];
356 |   var lines = ["== By weekday =="];
357 |   var max = 0;
358 |   for (var k in counts) {
359 |     if (counts[k] > max) {
