387 |     tags: Object.keys(countByTag(notes)).length,
388 |     averageLength: Math.round(averageLength(notes)),
389 |     busiestDay: topEntries(countByWeekday(notes), 1).map(function (e) { return e.key; })[0] || null,
390 |   };
391 | }
