393 | function compareSummaries(before, after) {
394 |   var diff = {};
395 |   var keys = ["total", "tags", "averageLength"];
396 |   for (var i = 0; i < keys.length; i++) {
397 |     var k = keys[i];
398 |     diff[k] = (after[k] || 0) - (before[k] || 0);
399 |   }
400 |   diff.busiestDayChanged = before.busiestDay !== after.busiestDay;
401 |   return diff;
402 | }
