404 | function describeChange(diff) {
405 |   var parts = [];
406 |   if (diff.total) {
407 |     parts.push((diff.total > 0 ? "+" : "") + formatNumber(diff.total) + " notes");
408 |   }
409 |   if (diff.tags) {
410 |     parts.push((diff.tags > 0 ? "+" : "") + diff.tags + " tags");
411 |   }
412 |   if (diff.averageLength) {
413 |     parts.push("average length " + (diff.averageLength > 0 ? "up " : "down ") + Math.abs(diff.averageLength) + " chars");
414 |   }
415 |   if (diff.busiestDayChanged) {
416 |     parts.push("busiest day changed");
417 |   }
418 |   return parts.length ? parts.join(", ") : "no change";
419 | }
