/*
 * Legacy reporting module (2019). Builds the nightly usage report that ops emails out.
 * Written before the ESM migration; still used by scripts/nightly (not in this repo).
 * Please do not change the output format without telling ops.
 */

import { normalizeWhitespace, truncate } from '../utils/strings.js';

const DAY_MS = 24 * 60 * 60 * 1000;
const DEFAULT_LOCALE = 'en-US';
const MAX_TOP = 10;
const WEEKDAY_NAMES = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
const WEEKDAY_ORDER = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
const SECTION_CONFIG = {
  daily: { label: 'Daily', days: 1 },
  weekly: { label: 'Weekly', days: 7 },
  monthly: { label: 'Monthly', days: 30 },
  quarterly: { label: 'Quarterly', days: 91 },
};
const numberFormatter = new Intl.NumberFormat(DEFAULT_LOCALE);

const pad2 = n => String(n).padStart(2, '0');

function formatDate(value) {
  const date = new Date(value);
  return Number.isNaN(date.getTime())
    ? 'unknown'
    : `${date.getFullYear()}-${pad2(date.getMonth() + 1)}-${pad2(date.getDate())}`;
}

const formatNumber = value => (value == null ? '-' : numberFormatter.format(Math.round(value)));
const percent = (part, total) => (!total ? '0%' : `${Math.round(((part / total) * 100) * 10) / 10}%`);
const withinDays = (notes, days, now) => notes.filter(({ createdAt }) => new Date(createdAt).getTime() >= (now || Date.now()) - days * DAY_MS);

function countBy(notes, iteratee) {
  return notes.reduce((counts, note) => {
    for (const key of iteratee(note)) counts[key] = (counts[key] || 0) + 1;
    return counts;
  }, {});
}

const countByTag = notes => countBy(notes, note => note.tags || []);
const countByAuthor = notes => countBy(notes, note => [note.author || 'unknown']);
const averageLength = notes => (notes.length ? notes.reduce((total, { body = '' }) => total + body.length, 0) / notes.length : 0);
const longestNote = notes => notes.reduce((best, note) => ((note.body || '').length > ((best?.body) || '').length ? note : best), null);

function topEntries(counts, limit = MAX_TOP) {
  return Object.entries(counts)
    .map(([key, value]) => ({ key, value }))
    .sort((a, b) => b.value - a.value || (a.key < b.key ? -1 : 1))
    .slice(0, limit);
}

function buildPeriodSection(notes, now, section) {
  const recent = withinDays(notes, section.days, now);
  const tags = topEntries(countByTag(recent), 5);
  const authors = topEntries(countByAuthor(recent), 5);
  const longest = longestNote(recent);
  const lines = [
    `== ${section.label} (last ${section.days} day${section.days === 1 ? '' : 's'}) ==`,
    `Notes created: ${formatNumber(recent.length)}`,
    `Share of all notes: ${percent(recent.length, notes.length)}`,
    `Average length: ${formatNumber(averageLength(recent))} chars`,
  ];

  if (tags.length) {
    lines.push('Top tags:', ...tags.map(({ key, value }, index) => `  ${index + 1}. ${key} (${value})`));
  } else {
    lines.push('Top tags: none');
  }

  if (authors.length) {
    lines.push('Most active:', ...authors.map(({ key, value }) => `  ${key}: ${value}`));
  }

  if (longest) {
    lines.push(`Longest note: ${truncate(normalizeWhitespace(longest.title), 40)} (${formatDate(longest.createdAt)})`);
  }

  return lines.join('\n');
}

const buildHeader = (title, now) => ['='.repeat(60), title, `Generated: ${formatDate(now || Date.now())}`, '='.repeat(60)].join('\n');
const buildFooter = notes => ['-'.repeat(60), `Total notes: ${formatNumber(notes.length)}`, `Distinct tags: ${Object.keys(countByTag(notes)).length}`, 'Report format v3. Questions: #ops-reports'].join('\n');

function toCsvRow(values) {
  return values
    .map(value => {
      let text = value == null ? '' : String(value);
      if (text.includes(',') || text.includes('"')) text = `"${text.replace(/"/g, '""')}"`;
      return text;
    })
    .join(',');
}

const buildCsv = notes => [
  toCsvRow(['id', 'title', 'author', 'tags', 'created']),
  ...notes.map(note => toCsvRow([note.id, note.title, note.author, (note.tags || []).join(' '), formatDate(note.createdAt)])),
].join('\n');

function validateOptions(options = {}) {
  const result = { sections: ['daily', 'weekly', 'monthly'], format: 'text', now: Date.now() };

  if (options.sections) {
    if (!Array.isArray(options.sections)) throw new Error('sections must be an array');
    result.sections = options.sections;
  }

  if (options.format) {
    if (!['text', 'csv'].includes(options.format)) throw new Error(`unknown format: ${options.format}`);
    result.format = options.format;
  }

  if (options.now) result.now = options.now;
  return result;
}

function buildReport(notes, options) {
  const opts = validateOptions(options);
  if (opts.format === 'csv') return buildCsv(notes);

  const parts = [buildHeader('Notes usage report', opts.now)];
  for (const name of opts.sections) {
    parts.push(SECTION_CONFIG[name] ? buildPeriodSection(notes, opts.now, SECTION_CONFIG[name]) : `(unknown section: ${name})`);
  }
  parts.push(buildFooter(notes));
  return parts.join('\n\n');
}

const escapeHtml = value => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');

const weekdayName = value => WEEKDAY_NAMES[new Date(value).getDay()];
const countByWeekday = notes => countBy(notes, note => [weekdayName(note.createdAt)]);

function buildWeekdaySection(notes) {
  const counts = countByWeekday(notes);
  const max = Math.max(0, ...Object.values(counts));
  return ['== By weekday ==', ...WEEKDAY_ORDER.map(day => {
    const count = counts[day] || 0;
    const bar = max ? '#'.repeat(Math.round((count / max) * 30)) : '';
    return `${`${day}          `.slice(0, 10)} ${bar} ${count}`;
  })].join('\n');
}

const buildHtml = (notes, options) => [
  '<!doctype html>',
  '<html>',
  '<head>',
  '<meta charset="utf-8">',
  '<title>Notes usage report</title>',
  '</head>',
  '<body>',
  '<pre>',
  ...buildReport(notes, options).split('\n').map(escapeHtml),
  '</pre>',
  '</body>',
  '</html>',
].join('\n');

function summarize(notes) {
  return {
    total: notes.length,
    tags: Object.keys(countByTag(notes)).length,
    averageLength: Math.round(averageLength(notes)),
    busiestDay: topEntries(countByWeekday(notes), 1).map(({ key }) => key)[0] || null,
  };
}

function compareSummaries(before, after) {
  const diff = {};
  for (const key of ['total', 'tags', 'averageLength']) diff[key] = (after[key] || 0) - (before[key] || 0);
  diff.busiestDayChanged = before.busiestDay !== after.busiestDay;
  return diff;
}

function describeChange(diff) {
  const parts = [];
  if (diff.total) parts.push(`${diff.total > 0 ? '+' : ''}${formatNumber(diff.total)} notes`);
  if (diff.tags) parts.push(`${diff.tags > 0 ? '+' : ''}${diff.tags} tags`);
  if (diff.averageLength) parts.push(`average length ${diff.averageLength > 0 ? 'up' : 'down'} ${Math.abs(diff.averageLength)} chars`);
  if (diff.busiestDayChanged) parts.push('busiest day changed');
  return parts.length ? parts.join(', ') : 'no change';
}

export { buildHtml, buildWeekdaySection, summarize, compareSummaries, describeChange, buildReport, buildCsv, formatDate, formatNumber, percent, countByTag, topEntries };
